// Async entry point - returns adapter for non-blocking handshake
inline error_t httpServerEstablishSecureConnectionAsync(
    HttpConnection* connection,
    TlsHandshakeAdapter** outAdapter)
{
    if (connection == nullptr || outAdapter == nullptr) {
        return ERROR_INVALID_PARAMETER;
    }

    if (connection->tlsContext == nullptr) {
        return ERROR_NOT_CONFIGURED;
    }

    TlsHandshakeAdapter* adapter = new TlsHandshakeAdapter();

    error_t error = adapter->start(connection);

    if (error != NO_ERROR) {
        delete adapter;
        *outAdapter = nullptr;
        return error;
    }

    *outAdapter = adapter;
    return NO_ERROR;
}

// Tick helper - advances handshake one step, returns completion info
// Caller is responsible for delivering completion event via seve event channel
inline TlsHandshakeStatus httpServerTlsHandshakeTick(
    TlsHandshakeAdapter* adapter,
    bool* outComplete,
    TlsHandshakeCompleteEvent* outEvent)
{
    if (adapter == nullptr) {
        if (outComplete) *outComplete = true;
        if (outEvent) {
            outEvent->connection = nullptr;
            outEvent->result = ERROR_INVALID_PARAMETER;
            outEvent->success = false;
        }
        return TlsHandshakeStatus::ERROR;
    }

    TlsHandshakeStatus status = adapter->progress();

    switch (status) {
        case TlsHandshakeStatus::DONE:
            if (outComplete) *outComplete = true;
            if (outEvent) *outEvent = adapter->getCompletionEvent();
            break;

        case TlsHandshakeStatus::ERROR:
            if (outComplete) *outComplete = true;
            if (outEvent) *outEvent = adapter->getCompletionEvent();
            break;

        case TlsHandshakeStatus::IN_PROGRESS:
        default:
            if (outComplete) *outComplete = false;
            if (outEvent) {
                outEvent->connection = adapter->getConnection();
                outEvent->result = NO_ERROR;
                outEvent->success = false;
            }
            break;
    }

    return status;
}

// Cleanup helper
inline void httpServerTlsHandshakeCleanup(TlsHandshakeAdapter* adapter) {
    delete adapter;
}
